 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = max({v for row in g for v in row}, key=lambda v: sum(row.count(v) for row in g))
    horizontal = [r for r in range(h) if all(v == 2 for v in g[r])]
    vertical = [c for c in range(w) if all(g[r][c] == 2 for r in range(h))]
    motif = [(r, c, g[r][c]) for r in range(h) for c in range(w)
             if g[r][c] not in (bg, 2, 8)]
    if not motif:
        return g
    rs = [r for r, c, v in motif]
    cs = [c for r, c, v in motif]

    # Move the colored motif next to the guide bar. Then place an 8 bar
    # immediately beyond the motif, on the side away from the guide.
    if horizontal:
        guide = horizontal[0]
        dr = guide + 1 - min(rs) if min(rs) > guide else guide - 1 - max(rs)
        shifted = [(r + dr, c, v) for r, c, v in motif]
        # Clear original motif before drawing its translated copy.
        for r, c, v in motif:
            g[r][c] = bg
        for r, c, v in shifted:
            if 0 <= r < h:
                g[r][c] = v
        marker = max(r for r, c, v in shifted) + 1 if min(rs) > guide else min(r for r, c, v in shifted) - 1
        if 0 <= marker < h:
            g[marker] = [8] * w
    elif vertical:
        guide = vertical[0]
        dc = guide + 1 - min(cs) if min(cs) > guide else guide - 1 - max(cs)
        shifted = [(r, c + dc, v) for r, c, v in motif]
        for r, c, v in motif:
            g[r][c] = bg
        for r, c, v in shifted:
            if 0 <= c < w:
                g[r][c] = v
        marker = max(c for r, c, v in shifted) + 1 if min(cs) > guide else min(c for r, c, v in shifted) - 1
        if 0 <= marker < w:
            for r in range(h):
                g[r][marker] = 8
    return g

